import{_ as a,o as t,c as n,a0 as r}from"./chunks/framework.BQGW-Zpy.js";const u=JSON.parse('{"title":"Compliance Data & Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"legal/compliance-data.md","filePath":"legal/compliance-data.md"}'),i={name:"legal/compliance-data.md"};function o(s,e,d,c,h,l){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="compliance-data-privacy" tabindex="-1">Compliance Data &amp; Privacy <a class="header-anchor" href="#compliance-data-privacy" aria-label="Permalink to &quot;Compliance Data &amp; Privacy&quot;">​</a></h1><h2 id="what-s-stored-and-where" tabindex="-1">What&#39;s stored, and where <a class="header-anchor" href="#what-s-stored-and-where" aria-label="Permalink to &quot;What&#39;s stored, and where&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Storage</th><th>On Hedera?</th></tr></thead><tbody><tr><td>Name, address, KYC documents</td><td>Off-chain, with the licensed party</td><td>Never</td></tr><tr><td>Full transaction amount / currency</td><td>Off-chain</td><td>Never</td></tr><tr><td>SHA-256 hash of a canonical compliance/quote/routing record</td><td>Local DB + HCS</td><td>Yes</td></tr><tr><td>A pseudonymous transfer reference</td><td>Local DB + HCS</td><td>Yes</td></tr><tr><td>Consensus timestamp</td><td>Issued by Hedera</td><td>Yes, by construction</td></tr></tbody></table><h2 id="canonicalisation" tabindex="-1">Canonicalisation <a class="header-anchor" href="#canonicalisation" aria-label="Permalink to &quot;Canonicalisation&quot;">​</a></h2><p>Two logically identical records, regardless of the order their fields were built in, must always hash to the same value, or the core verification claim (&quot;recompute and compare&quot;) would be unreliable. <code>hashing.mjs</code>&#39;s <code>canonicalHash()</code> recursively sorts object keys before hashing to guarantee this. Covered by unit tests in <code>backend/services/hedera/__tests__/hashing.test.mjs</code>.</p><h2 id="why-plain-hashing-isn-t-enough-for-identifiers" tabindex="-1">Why plain hashing isn&#39;t enough for identifiers <a class="header-anchor" href="#why-plain-hashing-isn-t-enough-for-identifiers" aria-label="Permalink to &quot;Why plain hashing isn&#39;t enough for identifiers&quot;">​</a></h2><p>A transfer reference, phone number, or account number has far too little entropy to hash safely on its own. An attacker can hash every plausible value in seconds and match it against what&#39;s anchored publicly. <code>pseudoRef()</code> uses <strong>HMAC with a secret pepper</strong> (<code>HEDERA_PSEUDO_PEPPER</code>, kept only in <code>.env</code>, never anchored anywhere) specifically to close that door. See the <code>pseudoRef</code> tests for confirmation that the same identifier with a different pepper produces an unrelated reference.</p><h2 id="right-to-erasure-vs-an-immutable-ledger" tabindex="-1">Right to erasure vs. an immutable ledger <a class="header-anchor" href="#right-to-erasure-vs-an-immutable-ledger" aria-label="Permalink to &quot;Right to erasure vs. an immutable ledger&quot;">​</a></h2><p>Because only a hash lives on-chain and the plaintext lives off-chain, erasure is achieved by destroying the off-chain record and its key. The anchor then verifies nothing and reveals nothing. This is the standard reconciliation between GDPR and an append-only ledger, adopted deliberately here.</p><h2 id="where-kyc-verification-itself-is-heading" tabindex="-1">Where KYC verification itself is heading <a class="header-anchor" href="#where-kyc-verification-itself-is-heading" aria-label="Permalink to &quot;Where KYC verification itself is heading&quot;">​</a></h2><p>Today, KYC in this design (and in every partner named in this project) still runs on document-based verification: a passport or ID scan, checked by the licensed partner performing the on-ramp or payout. That step, not the settlement layer, is the slowest and most fraud-exposed part of onboarding a new sender or recipient.</p><p>A real, dated development worth tracking: on 16 July 2026, the European Commission published results of an EU-Japan interoperability pilot between the EUDI Wallet (EU Digital Identity Wallet) and Japan&#39;s My Number Card system. The pilot confirmed that government-issued digital identity credentials can be issued, stored, presented, and verified across two jurisdictions with completely different technical and governance architectures, using open standards rather than a shared framework. Tested use cases included cross-border bank account opening. Japan is separately expanding My Number Card from a government-only credential into a platform private-sector services (banks, telecoms) can verify against directly.</p><p><strong>What this means for this project, if it matures:</strong> a licensed partner&#39;s KYC check could eventually verify a government-issued digital credential cryptographically rather than a document scan, for both sides of a transfer, not just within one jurisdiction. That would make the partner&#39;s KYC step faster and less exposed to document/photo fraud, and would make our own compliance-anchoring model a more natural fit for a world where the <em>input</em> to KYC is already a verifiable credential rather than a photo.</p><p><strong>Note, from the pilot&#39;s own report:</strong> the technology works; mutual legal recognition between jurisdictions does not exist yet, and building it is a multi-year regulatory process, not a technical one. This is a direction to watch, not a dependency this project has today.</p>',14)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
